-- ── 16. CONTRACT REGISTER ──────────────────────────────────────────────────
-- Three clause templates, a generated contract for every sale, and the
-- company's own paperwork. The generated contracts carry all three
-- e-signature states — signed, still out, and declined — so that screen has
-- each of its branches on show.
do $$
begin
  insert into public.contract_templates (id, admin_id, template_name, contract_type,
    signatory_name, signatory_title, ownership_clause, default_clause, insurance_clause,
    penalty_clause, settlement_clause, governing_law_clause, is_default, is_active)
  select v.id::uuid, c.admin_id, v.name, v.ctype, v.sig_name, v.sig_title,
    v.ownership, v.dflt, v.insurance, v.penalty, v.settlement, v.law, v.is_default, true
  from _demo_ctx c, (values
    ('df8754ec-74b2-5cc0-b26b-02a1544d3d42', 'Hire Purchase Agreement', 'hire_purchase', 'Grace Wanjiru', 'Managing Director', 'Title in the goods remains with the Seller until the final instalment is received in cleared funds.', 'Two consecutive missed instalments place the Buyer in default and the full balance becomes due on demand.', 'The Buyer shall keep the goods comprehensively insured for their full replacement value, with the Seller noted as loss payee.', 'A late payment charge of 2% per month accrues on any instalment outstanding for more than seven days.', 'The Buyer may settle early at any time; interest is rebated on the actuarial basis to the date of settlement.', 'This agreement is governed by the laws of Kenya, and the parties submit to the courts at Nairobi.', true),
    ('2e85299f-7951-5163-a1db-6b2e8d9e4042', 'Cash Sale Agreement', 'cash_sale', 'Grace Wanjiru', 'Managing Director', 'Title and risk pass to the Buyer on payment in full and collection of the goods.', 'Goods not collected within fourteen days of payment may be charged storage at the prevailing rate.', 'The Buyer insures the goods from the moment risk passes.', 'Not applicable to a cash sale.', 'Not applicable to a cash sale.', 'This agreement is governed by the laws of Kenya, and the parties submit to the courts at Nairobi.', false),
    ('720611c8-34a9-54d6-83da-23f9355d083e', 'Equipment Hire Terms', 'general', 'Grace Wanjiru', 'Managing Director', 'The equipment remains at all times the property of the Owner.', 'Hire charges unpaid for thirty days entitle the Owner to repossess without notice.', 'The Hirer insures against damage, theft and third party liability for the whole hire period.', 'Equipment returned late is charged at 150% of the daily rate for each day of delay.', 'Hire may be ended early on seven days written notice; charges are due to the end of the notice period.', 'This agreement is governed by the laws of Kenya, and the parties submit to the courts at Nairobi.', false)
  ) as v(id, name, ctype, sig_name, sig_title, ownership, dflt, insurance, penalty,
         settlement, law, is_default)
  on conflict do nothing;
exception
  when undefined_table or undefined_column then
    raise notice 'Skipped contract_templates: % — that table is not in this database, everything else is unaffected.', sqlerrm;
end $$;

