-- ── 19. WHAT LANDED ────────────────────────────────────────────────────────
-- Read this output before closing the editor. A zero anywhere means that
-- table rejected its rows, and the reason will be in the notices above.
select 'chart_of_accounts' as table_name, count(*) as rows from public.chart_of_accounts where admin_id = (select admin_id from _demo_ctx)
union all select 'journal_entries',    count(*) from public.journal_entries    where admin_id = (select admin_id from _demo_ctx)
union all select 'user_profiles',      count(*) from public.user_profiles      where admin_id = (select admin_id from _demo_ctx)
union all select 'payroll_records',    count(*) from public.payroll_records    where admin_id = (select admin_id from _demo_ctx)
union all select 'clients',            count(*) from public.clients            where admin_id = (select admin_id from _demo_ctx)
union all select 'assets',             count(*) from public.assets             where admin_id = (select admin_id from _demo_ctx)
union all select 'agents',             count(*) from public.agents             where admin_id = (select admin_id from _demo_ctx)
union all select 'sales',              count(*) from public.sales              where admin_id = (select admin_id from _demo_ctx)
union all select 'payments',           count(*) from public.payments           where admin_id = (select admin_id from _demo_ctx)
union all select 'company_invoices',   count(*) from public.company_invoices   where admin_id = (select admin_id from _demo_ctx)
union all select 'bank_transactions',  count(*) from public.bank_transactions  where admin_id = (select admin_id from _demo_ctx)
union all select 'leads',              count(*) from public.leads              where admin_id = (select admin_id from _demo_ctx)
union all select 'crm_interactions',   count(*) from public.crm_interactions   where admin_id = (select admin_id from _demo_ctx)
union all select 'installment_schedules', count(*) from public.installment_schedules s
  join public.sales sa on sa.id = s.sale_id where sa.admin_id = (select admin_id from _demo_ctx)
order by table_name;

-- The ledger, read back through the chart the way the Statements tab reads
-- it. Every seeded account string has to find its account here — a class
-- with no rows means a journal line names something the chart does not
-- carry, and that line is invisible on the P&L and the balance sheet.
--
-- Expect: revenue and the two liability classes credit-heavy, assets and the
-- expense classes debit-heavy, and the balance column summing to zero.
with seeded as (
  select debit_account as account, amount as dr, 0::numeric as cr
    from public.journal_entries
   where admin_id = (select admin_id from _demo_ctx) and entry_no like 'DEMO-JE-%'
  union all
  select credit_account, 0::numeric, amount
    from public.journal_entries
   where admin_id = (select admin_id from _demo_ctx) and entry_no like 'DEMO-JE-%'
)
select coalesce(coa.account_type, 'UNMATCHED — check this') as account_class,
       round(sum(s.dr), 2) as debits,
       round(sum(s.cr), 2) as credits,
       round(sum(s.dr) - sum(s.cr), 2) as balance
  from seeded s
  left join public.chart_of_accounts coa
    on coa.admin_id = (select admin_id from _demo_ctx)
   and s.account = coa.account_code || ' — ' || coa.account_name
 group by 1
 order by 1;

